# -*- coding: utf-8 -*-
"""Extra dishes generated from real menu families. Imported by build_foods.py."""
from __future__ import annotations

from typing import Any


def extra_dishes(F, flavor, texture, C) -> list[dict[str, Any]]:
    LD, LDN, ALLDAY, BRUNCH = C["LD"], C["LDN"], C["ALLDAY"], C["BRUNCH"]
    SOLO, GRP, DATE, ALL_OCC = C["SOLO"], C["GRP"], C["DATE"], C["ALL_OCC"]
    DELIVER, HOME, REST, ALL_MODE = C["DELIVER"], C["HOME"], C["REST"], C["ALL_MODE"]
    items: list[dict[str, Any]] = []

    def add(**kw):
        meals = kw.pop("meals", LD)
        occ = kw.pop("occ", SOLO)
        modes = kw.pop("modes", ALL_MODE)
        flav = kw.pop("flav", None) or flavor()
        tex = kw.pop("tex", None) or texture()
        items.append(
            F(
                kw.pop("id"),
                kw.pop("ko"),
                kw.pop("en"),
                kw.pop("parent"),
                kw.pop("group"),
                kw.pop("cuisine"),
                kw.pop("region"),
                kw.pop("cat", "main"),
                kw.pop("dish", "stew"),
                kw.pop("carb", "rice"),
                kw.pop("protein", "pork"),
                flav,
                tex,
                kw.pop("sat", 3),
                kw.pop("hp", 3),
                kw.pop("adv", 1),
                meals,
                occ,
                modes,
                kw.pop("price", 2),
                kw.pop("pop", 3),
                kw.pop("kw", None) or [],
                temp=kw.pop("temp", "hot"),
                prep=kw.pop("prep", 2),
                diet=kw.pop("diet", None),
                allergens=kw.pop("allg", None),
                season=kw.pop("season", None),
            )
        )
        if kw:
            raise SystemExit("unused keys " + ",".join(kw))

    def fam(rows, **base):
        for row in rows:
            spec = dict(base)
            spec.update(row)
            add(**spec)

